 private static String read(InputStream in)throws IOException{if(in==null)return "{}";ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){bytes.write(buffer,0,n);if(bytes.size()>3_000_000)throw new IOException("Response too large");}return bytes.toString("UTF-8");}
