 private void request(String path,JSONObject body,Result result){requestAt(BASE+path,body,true,result);}
 private void requestAt(String url,JSONObject body,boolean authenticated,Result result){
  final String auth=token;
  executor.execute(()->{try{
   HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();
   c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(20000);
   c.setRequestProperty("Accept","application/json");
   if(url.startsWith(BASE+"/"))c.setRequestProperty("Origin",BASE);
   c.setRequestProperty("User-Agent","LQADWA/1.0.6 ("+BASE+")");
   if(authenticated&&!auth.isEmpty())c.setRequestProperty("X-Lqadwa-Session",auth);
   if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}
   int status=c.getResponseCode();JSONObject value;
   try(InputStream in=status>=400?c.getErrorStream():c.getInputStream()){value=new JSONObject(read(in));}finally{c.disconnect();}
   if(status>=300)throw new ApiError(status,value.optString("error",t("error")));
   runOnUiThread(()->{
    if(isFinishing()||isDestroyed()||(authenticated&&!auth.equals(token)))return;
    try{result.accept(value);}catch(Exception e){busy=false;showProgress(false);error(e.getMessage());}
   });
  }catch(Exception e){runOnUiThread(()->{
   if(isFinishing()||isDestroyed()||(authenticated&&!auth.equals(token)))return;
   busy=false;linking=false;showProgress(false);
   if(e instanceof ApiError&&(((ApiError)e).status==401||((ApiError)e).status==410)&&authenticated)logoutLocal();
   else if(e instanceof ApiError&&((ApiError)e).status==403&&authenticated&&body==null&&url.equals(BASE+"/api/app")){logoutLocal();error(t("applicationSuspended"));}
   else error(e instanceof ApiError ? authError(e.getMessage()) : extra("تعذّر الاتصال. تحقق من الإنترنت وأعد المحاولة.","Connexion indisponible. Vérifiez Internet et réessayez.","Connection unavailable. Check the network and retry.","Ulac tuqqna. Ɛreḍ tikkelt nniḍen."));
  });}});
 }
 private static class ApiError extends Exception{final int status;ApiError(int status,String msg){super(msg);this.status=status;}}
 private void showProgress(boolean visible){if(progress!=null)progress.setVisibility(visible?View.VISIBLE:View.GONE);}
 private void load(boolean first){showProgress(true);request("/api/app",null,value->{data=value;busy=false;showProgress(false);if(first){JSONObject profile=data.optJSONObject("profile");if(profile!=null)city=profile.optString("city","algiers");}render();});}
 private void mutate(JSONObject input,Result after){if(busy)return;busy=true;showProgress(true);request("/api/app",input,value->{data=value;busy=false;showProgress(false);if(after!=null)after.accept(value);else render();});}
