 private static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte n:b)s.append(String.format(Locale.ROOT,"%02x",n));return s.toString();}
 private String authError(String code){
  if("CREDENTIALS".equals(code))return extra("تحقق من البريد وكلمة المرور وتأكيد بريدك.","Vérifiez l’e-mail, le mot de passe et la confirmation de votre adresse.","Check your email, password and email confirmation.","Senqed imayl d wawal uffir.");
  if("RATE_LIMIT".equals(code))return extra("محاولات كثيرة. حاول بعد قليل.","Trop de tentatives. Réessayez plus tard.","Too many attempts. Try again shortly.","Ɛreḍ tikkelt nniḍen.");
  if("UNAVAILABLE".equals(code)||"FIELDS".equals(code))return extra("تعذّر تسجيل الدخول. تحقق من البيانات وأعد المحاولة.","Connexion impossible. Vérifiez les champs et réessayez.","Unable to sign in. Check the fields and retry.","Ur nezmir ara ad nekcem. Senqed isefka.");
  return code;
 }
 private void nativeLogin(){
  LinearLayout form=column();form.setPadding(dp(22),dp(8),dp(22),dp(16));
  form.setLayoutDirection(language.equals("ar")?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);
  EditText email=field(form,extra("البريد الإلكتروني","Adresse e-mail","Email address","Imayl"),"",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);
  EditText password=field(form,extra("كلمة المرور","Mot de passe","Password","Awal uffir"),"",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);
  email.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);password.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);
  ScrollView scroll=new ScrollView(this);scroll.addView(form);
  androidx.appcompat.app.AlertDialog dialog=new MaterialAlertDialogBuilder(this).setTitle(t("login")).setView(scroll).setNegativeButton(t("cancel"),null).create();
  button(t("login"),form,()->{
   String address=email.getText().toString().trim();
   if(!android.util.Patterns.EMAIL_ADDRESS.matcher(address).matches()){email.setError(extra("بريد غير صالح","Adresse invalide","Invalid email","Imayl arameɣtu"));return;}
   if(password.getText().length()==0){password.setError(extra("أدخل كلمة المرور","Saisissez le mot de passe","Enter your password","Aru awal uffir"));return;}
   busy=true;showProgress(true);
   requestAt(BASE+"/api/auth",obj("action","login","email",address,"password",password.getText().toString(),"native",true),false,r->{
    token=r.getString("token");session.save(token);password.setText("");deviceId="";verifier="";deviceCode="";busy=false;dialog.dismiss();load(true);
   });
  },true);
  button(t("signup"),form,()->{dialog.dismiss();startLink();},false);
  button(extra("نسيت كلمة المرور؟","Mot de passe oublié ?","Forgot password?","Tettud awal uffir?"),form,()->open(BASE+"/login?mode=recover"),false);
  dialog.show();
  requestAt(BASE+"/api/auth/providers",null,false,providers->{
   if(!dialog.isShowing()||!token.isEmpty())return;
   if(providers.optBoolean("google"))button(extra("المتابعة باستخدام Google","Continuer avec Google","Continue with Google","Kemmel s Google"),form,()->{dialog.dismiss();startLink("login");},false);
   if(providers.optBoolean("apple"))button(extra("المتابعة باستخدام Apple","Continuer avec Apple","Continue with Apple","Kemmel s Apple"),form,()->{dialog.dismiss();startLink("login");},false);
  });
 }
 private void startLink(){startLink("register");}
 private void startLink(String mode){if(!deviceId.isEmpty()&&deviceExpires>System.currentTimeMillis()){open(BASE+"/login?mode="+mode+"&return_to="+Uri.encode("/connect?id="+deviceId));return;}byte[] random=new byte[32];new SecureRandom().nextBytes(random);verifier=hex(random);try{String challenge=hex(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.UTF_8)));busy=true;showProgress(true);request("/api/device",obj("action","create","challenge",challenge),r->{busy=false;deviceId=r.getString("id");deviceCode=r.getString("code");deviceExpires=r.getLong("expires");render();new MaterialAlertDialogBuilder(this).setTitle(deviceCode).setMessage(extra("اكتب هذا الرمز بعد تسجيل الدخول في الصفحة الآمنة، ثم ارجع إلى التطبيق.","Saisissez ce code sur la page sécurisée après connexion, puis revenez dans l’application.","Enter this code on the secure page after signing in, then return to this app.","Aru tangalt deg usebter aɣelsan, syen uɣal-d ɣer usnas.")).setPositiveButton(t("continueLogin"),(d,w)->open(BASE+"/login?mode="+mode+"&return_to="+Uri.encode("/connect?id="+deviceId))).setNegativeButton(t("close"),null).show();});}catch(Exception e){error(t("error"));}}
 private void pollLink(){if(!resumed||linking||deviceId.isEmpty()||deviceExpires<System.currentTimeMillis())return;handler.removeCallbacks(linkLoop);linking=true;request("/api/device",obj("action","exchange","id",deviceId,"verifier",verifier),r->{linking=false;if(r.optBoolean("pending")){handler.postDelayed(linkLoop,5000);return;}token=r.getString("token");session.save(token);deviceId="";verifier="";deviceCode="";load(true);});}
 private Spinner cityPicker(LinearLayout parent){parent.addView(text(t("city"),14,MUTED));Spinner spinner=new Spinner(this);ArrayList<String> labels=new ArrayList<>();int selected=0;for(int i=0;i<cities.length();i++){JSONObject c=cities.optJSONObject(i);labels.add(c.optString(language.equals("ar")?"name":"latin"));if(c.optString("id").equals(city))selected=i;}ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels);spinner.setAdapter(adapter);spinner.setSelection(selected);spinner.setMinimumHeight(dp(52));parent.addView(spinner);return spinner;}
 private String selectedCity(Spinner spinner){return cities.optJSONObject(spinner.getSelectedItemPosition()).optString("id");}
 private JSONObject center(){for(JSONObject c:list(cities))if(c.optString("id").equals(city))return c;return obj("lat",36.75,"lng",3.05);}
 private void search(){content.addView(heading(t("searchHeading")));content.addView(text(t("welcomeSub"),16,MUTED));LinearLayout form=card(content);EditText medicine=field(form,t("medicine"),query,InputType.TYPE_CLASS_TEXT);Spinner area=cityPicker(form);CheckBox duty=new CheckBox(this);duty.setText(t("night"));duty.setChecked(night);form.addView(duty);button(t("location"),form,()->locate(()->{stopLocation();notice(form,extra("تم تحديد موقعك. تُرتّب الصيدليات حسب قربها منك ضمن الولاية المختارة.","Position obtenue. Les pharmacies de la wilaya choisie sont classées par proximité.","Location ready. Pharmacies in your selected wilaya are sorted by proximity.","Adig-ik yettwaf. Fren tamnaḍt-ik i unadi."));}),false);button(t("searchButton"),form,()->{query=medicine.getText().toString().trim();city=selectedCity(area);night=duty.isChecked();if(query.length()<2){medicine.setError(t("medicine"));return;}activeRequest=UUID.randomUUID().toString();mutate(obj("action","search","medicine",query,"city",city,"night",night,"demo",false,"token",activeRequest),r->{screen="results";render();});},true);button(t("scanMedicine")+" / "+extra("الوصفة","ordonnance","prescription","tamedyazt"),form,()->{query=medicine.getText().toString();imageChoice(false);},false);button(t("catalogMatch"),form,()->catalogChoice(medicine.getText().toString(),false),false);notice(form,t("privacy"));notice(content,t("alwaysFreePatient"));}
 
 
 private ArrayList<JSONObject> pharmacyList(){ArrayList<JSONObject> result=new ArrayList<>();for(JSONObject p:list(rows("pharmacies")))if(p.optString("city").equals(city)&&!p.optBoolean("pilot")&&(!night||p.optBoolean("duty")))result.add(p);Collections.sort(result,(a,b)->Double.compare(distance(a),distance(b)));return result;}
 private double distance(JSONObject p){float[] result=new float[1];JSONObject origin=center();Location.distanceBetween(position==null?origin.optDouble("lat"):position.getLatitude(),position==null?origin.optDouble("lng"):position.getLongitude(),p.optDouble("lat"),p.optDouble("lng"),result);return result[0];}
 private String distanceText(JSONObject p){double meters=distance(p);String value=meters<1000?Math.round(meters)+" m":String.format(Locale.getDefault(),"%.1f km",meters/1000);return position==null?t("approx")+" "+value:value;}
