 private void nativeMap(LatLng center,OnMapReadyCallback ready){
  MapView view=new MapView(this);mapView=view;content.addView(view,new LinearLayout.LayoutParams(-1,dp(350)));view.onCreate(null);view.onStart();if(resumed)view.onResume();
  view.getMapAsync(m->{if(mapView!=view||isDestroyed())return;String style="{\"version\":8,\"sources\":{\"osm\":{\"type\":\"raster\",\"tiles\":[\"https://tile.openstreetmap.org/{z}/{x}/{y}.png\"],\"tileSize\":256,\"attribution\":\"© OpenStreetMap contributors\"}},\"layers\":[{\"id\":\"osm\",\"type\":\"raster\",\"source\":\"osm\"}]}";m.setStyle(new Style.Builder().fromJson(style),s->{if(mapView!=view||isDestroyed())return;map=m;m.moveCamera(CameraUpdateFactory.newLatLngZoom(center,13));ready.onMapReady(m);if(arrivalBooking.isEmpty())updateMapLocation();});});
  content.addView(text(t("mapsCredit"),12,MUTED));
 }
 private void maps(){
  if(!arrivalBooking.isEmpty()){arrivalMap();return;}
  content.addView(heading(destination==null?t("mapTitle"):destination.optString("name")));
  if(destination==null){Spinner area=cityPicker(content);button(t("refresh"),content,()->{city=selectedCity(area);render();},false);}
  if(destination!=null){TextView address=text(destination.optString("area"),16,MUTED);address.setTextIsSelectable(true);content.addView(address);button(t("copyAddress"),content,()->{ClipboardManager clipboard=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newPlainText(t("address"),destination.optString("name")+" — "+destination.optString("area")));Toast.makeText(this,t("copied"),Toast.LENGTH_SHORT).show();},false);}
  notice(content,t("localTrackingNote"));
  button(t(mapTracking?"stopTracking":"followPosition"),content,this::toggleMapTracking,false);
  button(t("recenter"),content,()->locate(this::centerCurrentPosition),false);
  JSONObject center=destination==null?center():destination;
  nativeMap(new LatLng(center.optDouble("lat"),center.optDouble("lng")),m->{
   for(JSONObject p:pharmacyList())m.addMarker(new MarkerOptions().position(new LatLng(p.optDouble("lat"),p.optDouble("lng"))).title(p.optString("name")).snippet(p.optString("id")));
   if(destination!=null&&pharmacyById(destination.optString("id"))==null)m.addMarker(new MarkerOptions().position(new LatLng(destination.optDouble("lat"),destination.optDouble("lng"))).title(destination.optString("name")));
   m.setOnMarkerClickListener(marker->{JSONObject p=pharmacyById(marker.getSnippet());if(p!=null)details(p);return true;});
  });
  if(destination==null){for(JSONObject p:pharmacyList())pharmacyCard(p);}else{notice(content,t("routingConsent"));button(t("driving"),content,()->{travel="driving";locate(this::calculateRoute);},true);button(t("walking"),content,()->{travel="walking";locate(this::calculateRoute);},false);button(t("transitRail"),content,()->externalDirections("transit"),false);notice(content,t("transitCoverage"));button(t("openNavigation"),content,()->externalDirections(travel),false);}
 }
 private JSONObject sharedArrival(){for(JSONObject b:list(rows("staffBookings")))if(b.optString("id").equals(arrivalBooking))return b;return null;}
 private void arrivalMap(){
  content.addView(heading(extra("متابعة الاقتراب","Suivi d’approche","Arrival map","Takarḍa n tuɣalin")));
  JSONObject p=own(), b=sharedArrival();
  if(p==null||!p.optString("status").equals("approved")){notice(content,t("applicationPending"));button(t("pharmacy"),content,()->navigate("pharmacy"),false);return;}
  LatLng pharmacy=new LatLng(p.optDouble("latitude")/1e6,p.optDouble("longitude")/1e6);
  boolean fresh=b!=null&&!b.isNull("approachLat")&&!b.isNull("approachLng")&&b.optLong("approachUpdated")>System.currentTimeMillis()-60000&&b.optLong("expires")>System.currentTimeMillis()&&b.optString("status").equals("active");
  LatLng patient=fresh?new LatLng(b.optDouble("approachLat"),b.optDouble("approachLng")):null;
  notice(content,extra("الموقع تقريبي وبموافقة المريض، ويختفي بعد دقيقة دون تحديث. لا يؤكد الاستلام.","Position approximative, partagée avec accord. Elle disparaît après une minute sans mise à jour et ne confirme pas le retrait.","The patient shares an approximate position by consent. It disappears after one minute without updates and does not confirm pickup.","Adig s wazal, s usentem n umeḍlan. Ad yeffeɣ ma ulac asmir."));
  nativeMap(pharmacy,m->{m.addMarker(new MarkerOptions().position(pharmacy).title(p.optString("name")));if(patient!=null){m.addMarker(new MarkerOptions().position(patient).title(t("approaching")).snippet("≈ 100 m"));if(!patient.equals(pharmacy))m.moveCamera(CameraUpdateFactory.newLatLngBounds(new LatLngBounds.Builder().include(pharmacy).include(patient).build(),dp(35)));}});
  if(fresh){float[] meters=new float[1];Location.distanceBetween(pharmacy.getLatitude(),pharmacy.getLongitude(),patient.getLatitude(),patient.getLongitude(),meters);content.addView(text(t("approaching")+" "+Math.round(meters[0])+" m",16,GREEN));handler.postDelayed(arrivalExpiry,Math.max(1,b.optLong("approachUpdated")+60000-System.currentTimeMillis()));}
  else notice(content,extra("لا يوجد موقع مشترك حديث لهذا الحجز.","Aucune position récente partagée pour cette réservation.","No recent shared position for this booking.","Ulac adig amaynut yettwabḍan."));
  button(t("refresh"),content,()->load(false),true);button(t("pharmacy"),content,()->navigate("pharmacy"),false);
 }
 private void calculateRoute(){if(position==null||destination==null||System.currentTimeMillis()-lastRoute<1500)return;lastRoute=System.currentTimeMillis();JSONObject target=destination;MapLibreMap routeMap=map;String routeMode=travel;String profile=routeMode.equals("walking")?"foot":"car";String url="https://routing.openstreetmap.de/routed-"+profile+"/route/v1/"+(profile.equals("foot")?"foot":"driving")+"/"+position.getLongitude()+","+position.getLatitude()+";"+target.optDouble("lng")+","+target.optDouble("lat")+"?overview=full&geometries=geojson&steps=false";showProgress(true);requestAt(url,null,false,r->{showProgress(false);JSONArray routes=r.optJSONArray("routes");if(routes==null||routes.length()==0){error(t("routeError"));return;}JSONObject route=routes.getJSONObject(0);JSONArray coords=route.getJSONObject("geometry").getJSONArray("coordinates");ArrayList<LatLng> points=new ArrayList<>();for(int i=0;i<coords.length();i++){JSONArray pair=coords.getJSONArray(i);points.add(new LatLng(pair.getDouble(1),pair.getDouble(0)));}if(map!=null&&map==routeMap&&destination==target&&travel.equals(routeMode)){if(routeLine!=null)map.removePolyline(routeLine);routeLine=map.addPolyline(new PolylineOptions().addAll(points).color(GREEN).width(6));updateMapLocation();if(points.size()>1)map.animateCamera(CameraUpdateFactory.newLatLngBounds(new LatLngBounds.Builder().includes(points).build(),dp(28)));notice(content,Math.round(route.optDouble("duration")/60)+" "+t("minutes")+" · "+String.format(Locale.getDefault(),"%.1f km",route.optDouble("distance")/1000)+"\n"+t("routeEstimate"));}});}
 private void externalDirections(String mode){if(destination!=null){String origin=position!=null&&SystemClock.elapsedRealtimeNanos()-position.getElapsedRealtimeNanos()<60000000000L?"&origin="+position.getLatitude()+","+position.getLongitude():"";open("https://www.google.com/maps/dir/?api=1&destination="+destination.optDouble("lat")+","+destination.optDouble("lng")+"&travelmode="+mode+origin+(mode.equals("transit")?"":"&dir_action=navigate"));}}
 @SuppressWarnings("MissingPermission") private void updateMapLocation(){
  if(map==null||position==null||!arrivalBooking.isEmpty()||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED||SystemClock.elapsedRealtimeNanos()-position.getElapsedRealtimeNanos()>60000000000L)return;
  org.maplibre.android.location.LocationComponent component=map.getLocationComponent();
  if(!component.isLocationComponentActivated()){Style style=map.getStyle();if(style==null)return;component.activateLocationComponent(org.maplibre.android.location.LocationComponentActivationOptions.builder(this,style).useDefaultLocationEngine(false).build());}
  component.setLocationComponentEnabled(true);component.forceLocationUpdate(position);
 }
 private void centerCurrentPosition(){updateMapLocation();if(map!=null&&position!=null)map.animateCamera(CameraUpdateFactory.newLatLngZoom(new LatLng(position.getLatitude(),position.getLongitude()),16));}
 private void toggleMapTracking(){mapTracking=!mapTracking;if(!mapTracking&&sharing.isEmpty())stopLocation();render();if(mapTracking)locate(this::centerCurrentPosition);}
 private void locate(Runnable after){afterLocation=after;if(checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.ACCESS_FINE_LOCATION},51);return;}startLocation();}
 @SuppressWarnings("MissingPermission") private void startLocation(){if(token.isEmpty()||(afterLocation==null&&sharing.isEmpty()&&!mapTracking))return;stopLocation();locationListener=new LocationListener(){public void onLocationChanged(Location loc){if(locationListener!=this||token.isEmpty())return;position=loc;updateMapLocation();handler.removeCallbacks(locationTimeout);if(afterLocation!=null){Runnable task=afterLocation;afterLocation=null;task.run();}if(!sharing.isEmpty())sharePosition();}public void onStatusChanged(String p,int s,Bundle b){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}};try{boolean any=false;for(String provider:new String[]{LocationManager.NETWORK_PROVIDER,LocationManager.GPS_PROVIDER})if(locationManager.isProviderEnabled(provider)){locationManager.requestLocationUpdates(provider,mapTracking?3000:10000,mapTracking?3:10,locationListener);any=true;}if(!any){afterLocation=null;stopLocation();error(t("routeError"));return;}Toast.makeText(this,t("location"),Toast.LENGTH_SHORT).show();handler.postDelayed(locationTimeout,20000);}catch(SecurityException e){afterLocation=null;stopLocation();error(t("routeError"));}}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] granted){super.onRequestPermissionsResult(code,permissions,granted);if(code==51){if(checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED)startLocation();else{afterLocation=null;error(t("routeError"));}}}
 private void stopLocation(){handler.removeCallbacks(locationTimeout);if(locationManager!=null&&locationListener!=null)locationManager.removeUpdates(locationListener);locationListener=null;}
