 private void deleteAccount(){LinearLayout c=column();c.setPadding(dp(22),dp(16),dp(22),dp(16));notice(c,extra("حذف نهائي للحساب والطلبات والحجوزات والصيدلية والمخزون. تُلغى الحجوزات وتُفصل الهواتف. لحذف بيانات تسجيل الدخول أيضاً، افتح صفحة بيانات حسابك في المتصفح.","Suppression définitive du compte, des demandes, réservations, pharmacie et stocks. Pour effacer aussi les données de connexion, ouvrez la page de votre compte dans le navigateur.","Permanently delete account, requests, bookings, pharmacy and stock. Active bookings are cancelled and phones disconnected. To remove sign-in records too, open your account-data page in the browser.","Tukksa n umiḍan d yisefka. Ulac tuɣalin. Senqed talɣut s taɛrabt neɣ tefransist."));EditText word=field(c,extra("اكتب LQADWA للتأكيد","Saisissez LQADWA","Type LQADWA to confirm","Aru LQADWA"),"",InputType.TYPE_CLASS_TEXT);androidx.appcompat.app.AlertDialog dialog=new MaterialAlertDialogBuilder(this).setTitle(extra("حذف حسابي","Supprimer mon compte","Delete my account","Kkes amiḍan-iw")).setView(c).setNegativeButton(t("cancel"),null).create();button(t("confirm"),c,()->{if(!word.getText().toString().equals("LQADWA")){word.setError("LQADWA");return;}busy=true;showProgress(true);request("/api/account",obj("action","delete","confirmation","LQADWA"),r->{busy=false;dialog.dismiss();logoutLocal();open(BASE+"/account-data");});},true);dialog.show();}
 private void logoutLocal(){busy=false;linking=false;deviceId="";verifier="";deviceCode="";handler.removeCallbacks(linkLoop);sharing="";arrivalBooking="";destination=null;afterLocation=null;mapTracking=false;position=null;stopLocation();token="";session.clear();data=new JSONObject();screen="search";render();}
 private void imageChoice(boolean qr){scanQr=qr;String[] labels={extra("التقاط صورة","Prendre une photo","Take a photo","Ṭṭef tawlaft"),extra("اختيار صورة","Choisir une image","Choose image","Fren tawlaft")};new MaterialAlertDialogBuilder(this).setTitle(qr?t("scanQr"):t("scanMedicine")).setItems(labels,(d,n)->{if(n==1){Intent pick=new Intent(Intent.ACTION_GET_CONTENT);pick.setType("image/*");startActivityForResult(pick,71);}else try{File folder=new File(getCacheDir(),"images");folder.mkdirs();captureFile=File.createTempFile("scan-",".jpg",folder);captureUri=FileProvider.getUriForFile(this,getPackageName()+".fileprovider",captureFile);Intent camera=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);camera.putExtra(MediaStore.EXTRA_OUTPUT,captureUri);camera.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(camera,72);}catch(Exception e){error(t("error"));}}).show();}
 @Override protected void onActivityResult(int requestCode,int resultCode,Intent intent){super.onActivityResult(requestCode,resultCode,intent);if(resultCode!=RESULT_OK){clearCapture();return;}if(requestCode==71||requestCode==72){Uri uri=requestCode==72?captureUri:intent==null?null:intent.getData();if(uri==null)return;try{String scanSession=token;if(scanSession.isEmpty())return;InputImage image=InputImage.fromFilePath(this,uri);showProgress(true);if(scanQr){com.google.mlkit.vision.barcode.BarcodeScanner scanner=BarcodeScanning.getClient();scanner.process(image).addOnSuccessListener(codes->{boolean found=false;for(com.google.mlkit.vision.barcode.common.Barcode code:codes){String raw=code.getRawValue();if(raw!=null&&collecting!=null&&raw.startsWith("DAWA:"+collecting.optString("id")+":")){collectionCode.setText(raw.substring(raw.lastIndexOf(':')+1));found=true;break;}}if(!found)error(t("error"));}).addOnFailureListener(e->error(t("error"))).addOnCompleteListener(task->{scanner.close();clearCapture();showProgress(false);});}else{com.google.mlkit.vision.text.TextRecognizer reader=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);reader.process(image).addOnSuccessListener(result->{if(!isFinishing()&&scanSession.equals(token)&&!token.isEmpty())reviewOcr(result.getText());}).addOnFailureListener(e->error(t("error"))).addOnCompleteListener(task->{reader.close();clearCapture();showProgress(false);});}}catch(Exception e){showProgress(false);clearCapture();error(t("error"));}}}
 private void clearCapture(){if(captureFile!=null){captureFile.delete();captureFile=null;captureUri=null;}}
 private void reviewOcr(String raw){LinearLayout c=column();c.setPadding(dp(18),dp(12),dp(18),dp(12));notice(c,extra("قراءة محلية للنص اللاتيني المطبوع؛ خط اليد والعربية غير مضمونين. راجع النص والتركيز مع الصيدلي. لن تُرفع الصورة أو الوصفة.","OCR local du texte latin imprimé. Écriture manuscrite et arabe non prises en charge. Vérifiez avec le pharmacien ; aucune ordonnance envoyée.","On-device printed Latin text OCR. Handwriting and Arabic are not supported. Verify name and strength with a pharmacist. No prescription is uploaded.","Taɣuri n tira talatinit deg yibenk. Tira s ufus d taɛrabt ur ttwadhelent ara. Senqed ddwa ɣer usaysi."));EditText edit=field(c,extra("راجع النص","Vérifier le texte","Review extracted text","Senqed aḍris"),raw.length()>15000?raw.substring(0,15000):raw,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);edit.setMaxLines(8);new MaterialAlertDialogBuilder(this).setTitle(t("scanMedicine")).setView(c).setNegativeButton(t("close"),(d,w)->edit.setText("")).setPositiveButton(t("confirm"),(d,w)->{String text=edit.getText().toString();edit.setText("");catalogChoice(text,true);}).show();}
 private static String normalize(String value){return Normalizer.normalize(value,Normalizer.Form.NFKD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("[^\\p{L}\\p{N}]+"," ").trim();}
 private void catalogChoice(String raw,boolean prescription){String normalized=" "+normalize(raw)+" ";ArrayList<String> names=new ArrayList<>();for(int i=0;i<medicines.length();i++){JSONArray med=medicines.optJSONArray(i);String brand=med.optString(0),name=brand+" "+med.optString(1);String term=normalize(brand);boolean match=prescription?term.length()>=4&&normalized.contains(" "+term+" "):normalize(name+" "+med.optString(2)).contains(normalize(raw));if(match&&!names.contains(name)){names.add(name);if(!prescription&&names.size()>=20)break;}}if(names.isEmpty()){error(t("noCatalogMatch"));return;}new MaterialAlertDialogBuilder(this).setTitle(t("catalogCaution")).setItems(names.toArray(new String[0]),(d,n)->{query=names.get(n);screen="search";render();}).setNegativeButton(t("close"),null).show();}
 private void open(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(ActivityNotFoundException e){error(t("error"));}}
