 @Override public void onPause(){resumed=false;if(!sharing.isEmpty()){String id=sharing;sharing="";request("/api/app",obj("action","share-location","reservation",id,"enabled",false),r->{data=r;});}handler.removeCallbacks(refreshLoop);handler.removeCallbacks(linkLoop);afterLocation=null;mapTracking=false;stopLocation();if(mapView!=null)mapView.onPause();super.onPause();}
